from pathlib import Path
import subprocess,sys,time,json,hashlib,os
batch,label,*cmd=sys.argv[1:];home=Path(f'editorial/reviews/{batch}-independent-evidence');home.mkdir(exist_ok=True);env=dict(os.environ,CRIC_REVIEW_CANDIDATE_APP='/private/tmp/cric-author-a-resident/officina-di-fisica');t=time.monotonic();r=subprocess.run(cmd,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT);(home/(label+'.log')).write_bytes(r.stdout);(home/(label+'.json')).write_text(json.dumps({'scope':'actual independent preparation or targeted tests only_not_product_UI','command':cmd,'candidateApp':env['CRIC_REVIEW_CANDIDATE_APP'],'exitCode':r.returncode,'signal':-r.returncode if r.returncode<0 else None,'elapsedSeconds':time.monotonic()-t,'rawSha256':hashlib.sha256(r.stdout).hexdigest(),'humanApproval':'NOT_RUN','productUI':'NOT_RUN'},indent=2)+'\n');print(r.stdout.decode(),flush=True);r.check_returncode()
